// Docs screenshots of control verbs and Corporate's budgets, with MOCK data only: the real server in front of the mock
// adapter (controlsServer.ts), and demo mode for a Hermes bot. Regenerated by `npm run screenshots`.
import { fileURLToPath } from 'node:url';
import { expect, test } from '@playwright/test';
import { noServer, person } from './helpers';
import { type ControlsServer, routeTo, startControlsServer } from './controlsServer';

const out = (name: string) => fileURLToPath(new URL(`../../docs/screenshots/${name}`, import.meta.url));

test.describe('@screenshot control verbs and budgets', () => {
  let server: ControlsServer | null = null;
  test.afterEach(async () => {
    await server?.close();
    server = null;
  });

  test('a bot window: budget gauge, controls and the confirmation step', async ({ page, baseURL }) => {
    server = await startControlsServer({ pageOrigin: new URL(baseURL!).origin });
    await routeTo(page, server);
    await page.goto('/');
    await expect(page.locator('[data-person]')).toHaveCount(23);
    await page.waitForTimeout(1600);
    await person(page, /^Dwight Schrute — /).click();
    const win = page.getByRole('dialog', { name: 'Dwight Schrute' });
    await win.getByRole('button', { name: 'Reassign “Fax the paper order”' }).click();
    await win.getByTestId('control-confirm').getByRole('combobox').selectOption('jim');
    await expect(win.getByTestId('budget-gauge')).toContainText('125%');
    await page.screenshot({ path: out('controls-confirm.png') });
  });

  test('Corporate: the top-bar badge and budgets in Angela\'s ledger', async ({ page, baseURL }) => {
    server = await startControlsServer({ pageOrigin: new URL(baseURL!).origin, autoPause: true });
    await routeTo(page, server);
    await page.goto('/');
    await expect(page.locator('[data-person]')).toHaveCount(23);
    await page.waitForTimeout(1600);
    await page.getByTestId('corporate').click();
    await expect(page.getByTestId('ledger-budgets')).toContainText('Corporate froze the expense account');
    await page.screenshot({ path: out('corporate-budgets.png') });
  });

  test('a Hermes bot in demo mode: no pause, run a job now', async ({ page }) => {
    await noServer(page);
    await page.goto('/?demo=1');
    await expect(page.locator('[data-person]')).toHaveCount(23);
    await page.waitForTimeout(1600);
    await person(page, /^Kelly Kapoor — /).click();
    const win = page.getByRole('dialog', { name: 'Kelly Kapoor' });
    await win.getByRole('button', { name: 'Run “Post queue check” now' }).click();
    await expect(win.getByTestId('control-confirm')).toContainText('Run “Post queue check” now?');
    await page.screenshot({ path: out('controls-hermes-demo.png') });
  });
});
